eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   OurTeams: () => (/* binding */ OurTeams)\n/* harmony export */ });\n/* harmony import */ var _public_ourLeaders_dilipPalwe_jpg__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! ../../../../../public/ourLeaders/dilipPalwe.jpg */ \"(ssr)/./public/ourLeaders/dilipPalwe.jpg\");\n/* harmony import */ var _public_ourLeaders_MrMVPatil_jpeg__WEBPACK_IMPORTED_MODULE_1__ = __webpack_require__(/*! ../../../../../public/ourLeaders/MrMVPatil .jpeg */ \"(ssr)/./public/ourLeaders/MrMVPatil .jpeg\");\n/* harmony import */ var _public_ourLeaders_MrLSJoshi_jpeg__WEBPACK_IMPORTED_MODULE_2__ = __webpack_require__(/*! ../../../../../public/ourLeaders/MrLSJoshi.jpeg */ \"(ssr)/./public/ourLeaders/MrLSJoshi.jpeg\");\n/* harmony import */ var _public_ourLeaders_MrVBBhale_jpeg__WEBPACK_IMPORTED_MODULE_3__ = __webpack_require__(/*! ../../../../../public/ourLeaders/MrVBBhale.jpeg */ \"(ssr)/./public/ourLeaders/MrVBBhale.jpeg\");\n // Adjust the path as necessary\n\n\n\nconst OurTeams = [\n    {\n        slug: 1,\n        leaderName: \"Mr. Dilip G. Palve\",\n        position1: \"Resident Engineer\",\n        position2: \"Former Executive Engineer\",\n        image: _public_ourLeaders_dilipPalwe_jpg__WEBPACK_IMPORTED_MODULE_0__[\"default\"],\n        message1: \"Mr. Dilip G. Palve, a seasoned former Executive Engineer, now serves as the Resident Engineer for one of CDF Infra Con Private Limited's key NHAI projects. With his wealth of experience in civil engineering and infrastructure development, Mr. Palve brings invaluable expertise and practical insight to our team. Over the years, he has been instrumental in ensuring the seamless execution of large-scale projects, consistently meeting deadlines while upholding the highest standards of quality and safety.\",\n        message2: \"His hands-on approach, coupled with his deep understanding of technical and regulatory requirements, allows him to effectively oversee all aspects of the project. From managing day-to-day operations on-site to troubleshooting complex engineering challenges, Mr. Palve’s skill set ensures that the project runs efficiently, minimizing risks and delays. His attention to detail and commitment to precision are evident in every task he undertakes, whether it’s coordinating with contractors, managing resources, or ensuring strict adherence to timelines.\",\n        message3: \"Beyond his technical acumen, Mr. Palve excels at leading and motivating teams. His leadership style is rooted in clarity, trust, and collaboration, which has fostered a culture of accountability and high performance among his team members. His ability to manage diverse groups, resolve conflicts, and keep the project on track makes him an invaluable asset to CDF Infra Con. Mr. Palve’s dedication, work ethic, and strong problem-solving abilities not only contribute to the success of the current project but also inspire those around him to strive for excellence.\",\n        message4: null,\n        // \"Thank you for visiting our website. We look forward to collaborating with you to create enduring and impactful infrastructure solutions.\",\n        message5: null\n    },\n    {\n        slug: 2,\n        leaderName: \"Mr. M. V. Patil \",\n        position1: \"Advisor of the Company\",\n        position2: \"Former Secretary of PWD Maharashtra\",\n        image: _public_ourLeaders_MrMVPatil_jpeg__WEBPACK_IMPORTED_MODULE_1__[\"default\"],\n        message1: \"Mr. M. V. Patil, former Secretary of PWD Maharashtra and ex-President of the Indian Roads Congress (IRC), now serves as an esteemed advisor to CDF Infra Con Private Limited. With decades of leadership in infrastructure development, policy-making, and highway engineering, he brings unparalleled expertise and strategic vision to the organization.\",\n        message2: \"Throughout his distinguished career, Mr. Patil has championed innovation, quality, and sustainability in the road sector. As an advisor, he guides the company with a strong focus on technical excellence, compliance, and future-ready solutions. His leadership inspires a culture of professionalism, accountability, and continuous growth within the team.\",\n        message3: \"He was a President of IRC – Year 1999, Vice- President IABSE – Year 1998 & 2002, Chairman IIBE – Pune Centre 1990 to 1994, Member of Technical commission on Bridge Engineering – IABSE, Convener of Rural Road Committee, Convener of Sub –Group for State Roads – 10th Five Year Plan, Convener – Committee for Maintenance Norms for State Roads- MORT&H. He was  Member of Fact Finding Committee appointed by Maharashtra Govt. to look into the problem of Flooding in Mumbai in July 2005.\",\n        message4: null,\n        message5: null\n    },\n    {\n        slug: 3,\n        leaderName: \"Mr. V. B. Bhale\",\n        position1: \"Resident Engineer\",\n        position2: \"Former Chief Engineer\",\n        image: _public_ourLeaders_MrVBBhale_jpeg__WEBPACK_IMPORTED_MODULE_3__[\"default\"],\n        message1: \"Mr. V. B. Bhale, a former Chief Engineer of PWD Maharashtra, brings a wealth of experience to CDF Infra Con Private Limited. Having worked extensively in the Pradhan Mantri Gram Sadak Yojana (PMGSY), he has developed a deep understanding of rural and national highway infrastructure. Currently, Mr. Bhale is contributing his expertise to one of our significant NHAI projects, where his guidance has been instrumental in helping our team achieve major milestones.\",\n        message2: \"His extensive knowledge in project management, technical planning, and civil engineering has been a tremendous asset to the project. Mr. Bhale’s leadership and strategic insights have enabled the team to improve efficiency, adhere to stringent deadlines, and meet high-quality standards. His experience in handling large-scale infrastructure projects has enhanced the team's capability to tackle complex challenges and achieve optimal results.\",\n        message3: \"As a civil engineer, Mr. Bhale is known for his sharp problem-solving skills, meticulous attention to detail, and deep understanding of engineering principles. He excels in managing resources effectively, ensuring safety, and adhering to regulatory standards. His leadership not only enhances project execution but also fosters a culture of continuous learning and development within the team. With a strong focus on quality, innovation, and sustainability, Mr. Bhale’s contribution continues to elevate the standard of our work and drive the project’s success forward.\",\n        message4: null,\n        message5: null\n    },\n    {\n        slug: 4,\n        leaderName: \"Mr. L. S. Joshi\",\n        position1: \"Team Leader\",\n        position2: \"Former Superintending Engineer\",\n        image: _public_ourLeaders_MrLSJoshi_jpeg__WEBPACK_IMPORTED_MODULE_2__[\"default\"],\n        message1: \"Mr. L. S. Joshi, a former Superintending Engineer of PWD Maharashtra, is currently serving as the Team Leader for one of CDF Infra Con Private Limited's major NHAI projects. With his extensive experience in highway construction and infrastructure management, he has played a crucial role in ensuring the successful execution of this project. His in-depth knowledge of engineering practices, combined with his practical approach to problem-solving, has been integral in enhancing the project's efficiency and overall performance.\",\n        message2: \"Under Mr. Joshi’s leadership, the project has become more streamlined, with a heightened focus on quality, safety, and timely completion. His ability to make quick, well-informed decisions and his hands-on management style have significantly improved the coordination between teams, resulting in smoother operations and fewer delays. His commitment to maintaining high standards of technical and safety compliance has ensured the project progresses without compromising on quality.\",\n        message3: \"Beyond his technical expertise, Mr. Joshi is an exceptional team leader who fosters a positive, collaborative work environment. His guidance has motivated the team to strive for excellence, promoting a culture of continuous improvement. With his leadership, the team has grown both professionally and personally, further contributing to the success of the project. Mr. Joshi’s unwavering dedication to delivering exceptional results makes him a valuable asset to CDF Infra Con Private Limited.\",\n        message4: null,\n        message5: null\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/app/pages/ourLeaderShipMem/[slug]/data.js\n");

